public Write withBigtableOptions(BigtableOptions.Builder optionsBuilder) {
  checkNotNull(optionsBuilder, "optionsBuilder");
  BigtableOptions options = optionsBuilder.build();
  BigtableOptions.Builder clonedBuilder = options.toBuilder().setBulkOptions(options.getBulkOptions().toBuilder().setUseBulkApi(true).build());
  BigtableOptions optionsWithAgent;
  try {
    optionsWithAgent = clonedBuilder.setUserAgent(getUserAgent()).build();
  } catch (SecurityException | IllegalFormatException e) {
    // Handle the exception, e.g., logging and returning a default or null Write object, or re-throwing a more specific exception.
    // This is a placeholder for the actual handling logic.
    throw new RuntimeException("Failed to set user agent", e);
  }
  return new Write(optionsWithAgent, tableId, bigtableService);
}
